    init {
        require(catalog.size == 252) { "RULE_CATALOG_NORMATIVE must contain exactly 252 IDs" }
        require(catalog.map { it.ruleId }.distinct().size == 252) { "Duplicate RULE_ID in evidence registry" }
    }

    fun registeredRuleIds(): Set<String> = catalog.mapTo(linkedSetOf()) { it.ruleId }

    fun lookup(profile: RuleProfile, ruleId: String): EvidenceQueryResult {
        val normalized = ruleId.trim()
        val entry = catalog.firstOrNull { it.ruleId == normalized && it.appliesTo(profile) }
            ?: return EvidenceQueryResult(
                RuleTrace(EvidenceStatus.MISSING_EVIDENCE, emptyList(), "No canonical evidence registered for this profile; no fallback allowed"),
                "MISSING_EVIDENCE"
            )
        val evidence = RuleEvidence(entry.ruleId, profile, entry.source, entry.location)
        return EvidenceQueryResult(
            RuleTrace(entry.evidenceStatus, listOf(evidence), entry.catalogStatus),
            "${entry.source} ${entry.location}"
        )
    }

    private fun CatalogEvidence.appliesTo(profile: RuleProfile): Boolean = when (scope) {
        Scope.CLASSIC -> profile == RuleProfile.OSE_CLASSIC_FANTASY
        Scope.ADVANCED -> profile == RuleProfile.OSE_ADVANCED_FANTASY
        Scope.BOTH -> true
    }
}
